// Отримуємо вхідні дані з найпершої ноди (Webhook)
// ЗАМІНИ 'Google Chat Webhook' на точну назву твоєї першої ноди, якщо вона інша!
const webhookData = $node["[Webhook] Inbound Chat Listener / [Webhook] Слухач вхідних повідомлень чату"].json;
const agentOutput = $json.output; // Відповідь від AI

// Витягуємо Space (кімнату або DM)
const chatSpace = webhookData.body.commonEventObject.space ? webhookData.body.commonEventObject.space.name : webhookData.body.chat.messagePayload.space.name;

// Витягуємо Thread (нитку розмови), якщо вона є
const chatThread = webhookData.body.chat.messagePayload.message.thread ? webhookData.body.chat.messagePayload.message.thread.name : null;

return {
  output: agentOutput,
  chat_space: chatSpace,
  chat_thread: chatThread // Ми передамо це далі
};

